const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);let selected='rose';const model=$('#fighter');
function note(text){$('#motionNote').textContent=text;$('#motionNote').hidden=false}
function guard(){const names=model.availableAnimations||[];model.animationName=names.find(n=>n.includes('стойка'))||names[0];model.play();$('#motionNote').hidden=true}
model.addEventListener('load',guard);
$$('[data-fighter]').forEach(b=>b.onclick=()=>{selected=b.dataset.fighter;$$('[data-fighter]').forEach(x=>x.classList.toggle('selected',x===b));const rose=selected==='rose';$('#name').innerHTML=rose?'РОЗОВАЯ<br>ПАНТЕРА':'ОСТРОВНОЙ<br>БОЕЦ';$('#styleName').textContent=rose?'Быстрые серии • точность':'Тяжёлые удары • стойкость';$('#power').textContent=rose?'1 280':'1 340';[rose?72:91,rose?91:67,rose?65:83].forEach((v,i)=>{let row=$$('.stats>div')[i];row.querySelector('b').textContent=v;row.querySelector('em').style.width=v+'%'});model.src=selected+'-guard.glb';$$('[data-action]').forEach(x=>x.classList.toggle('selected',x.dataset.action==='guard'))});
$$('[data-action]').forEach(b=>b.onclick=()=>{$$('[data-action]').forEach(x=>x.classList.toggle('selected',x===b));if(b.dataset.action==='guard')guard();else if(b.dataset.action==='attack'){let a=model.availableAnimations.find(n=>n.includes('Jab'));if(a){model.animationName=a;model.play();note('Джеб · существующая боевая анимация')}else note('Показ ударов: следующий режим просмотра')}else{guard();note('Танец — место для анимации Meshy. Пока сохраняем боевую стойку.')}});
function sheet(kind){$('#sheet').hidden=false;$('#arenaOptions').hidden=kind!=='arena';$('#ruleOptions').hidden=kind!=='rules'}$('#arena').onclick=()=>sheet('arena');$('#settings').onclick=$('#editRules').onclick=()=>sheet('rules');$('#close').onclick=()=>$('#sheet').hidden=true;
$$('[data-arena]').forEach(b=>b.onclick=()=>{$('#arenaImage').src='../../assets/arena-'+b.dataset.arena+'.png';$('#arenaName').textContent=b.textContent.toUpperCase();$('#sheet').hidden=true});$('#save').onclick=()=>{$('#ruleSummary').textContent=$('#difficulty').value+' • '+$('#wins').value+' победы • '+$('#timer').value+' сек.';$('.rules>span').textContent=$('#mode').value.toUpperCase();$('#sheet').hidden=true};$('#start').onclick=()=>{$('#toast').textContent='Дизайн-прототип: переход в бой будет подключён в Unity';$('#toast').hidden=false};$('#back').onclick=()=>{$('#toast').textContent='Возврат в Game Hub';$('#toast').hidden=false};
